mergeItems(category: GatheredInfoCategory, itemIds: string[], mergedValue: string, source: InfoSource): InfoItem {
  const merged: InfoItem = {
    id: randomUUID(),
    value: mergedValue,
    source,
    addedAt: new Date().toISOString(),
  };

  const idSet = new Set(itemIds);
  this.info[category] = this.info[category].filter((item) => !idSet.has(item.id));
  this.info[category].push(merged);
  return merged;
}
